{
  "name": "prepare_technical_interview_help",
  "kind": "workflow",
  "description": "Helps users prepare for software development interviews with explanations, practice questions, model answers and feedback.",
  "signature": {
    "in": "{\"type\":\"object\",\"properties\":{\"topic\":{\"type\":\"string\"},\"role\":{\"type\":\"string\"},\"level\":{\"type\":\"string\"},\"mode\":{\"type\":\"string\"},\"question\":{\"type\":\"string\"}},\"required\":[\"topic\",\"question\"]}",
    "out": "output of s1"
  },
  "steps": [
    {
      "id": "s1",
      "uses": "answer_technical_interview_question",
      "foreach": null,
      "inputs": [
        {
          "param": "topic",
          "source": "$input.topic"
        },
        {
          "param": "role",
          "source": "$input.role"
        },
        {
          "param": "level",
          "source": "$input.level"
        },
        {
          "param": "mode",
          "source": "$input.mode"
        },
        {
          "param": "question",
          "source": "$input.question"
        }
      ]
    }
  ],
  "output_step": "s1",
  "permissions": {
    "net": [],
    "llm": true
  },
  "budget": {
    "max_tokens_per_run": 6000
  },
  "lineage": {
    "created_by": "factory",
    "uses": [
      "answer_technical_interview_question@v1"
    ]
  },
  "example_input": "{\"topic\":\"data structures and algorithms\",\"role\":\"backend software engineer\",\"level\":\"mid-level\",\"mode\":\"explain\",\"question\":\"How should I approach a coding interview question about detecting a cycle in a linked list, and what follow-up questions might the interviewer ask?\"}",
  "purpose": "make a bot which prepares user for technical software development related interviews",
  "version": 1,
  "headline": "{answer}",
  "examples": [
    "How do I explain the difference between a process and a thread in a systems interview?",
    "What should I expect in a system design interview for a senior frontend role?",
    "Can you quiz me on SQL joins and indexing for a junior data engineer interview?"
  ],
  "voice": "witch",
  "manual_minutes": 25.0,
  "manual_basis": "Research best practices for cycle detection algorithms, formulate explanation with code examples, anticipate follow-up questions, and compile comprehensive answer."
}

